CREATE TABLE public.portal_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text, permissions text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT portal_role_permissions CHECK (permissions <@ ARRAY['household.manage','issues.manage','audit.read']::text[]), CONSTRAINT portal_role_name CHECK (length(trim(name)) BETWEEN 2 AND 60));
GRANT SELECT ON public.portal_roles TO authenticated;
GRANT ALL ON public.portal_roles TO service_role;
ALTER TABLE public.portal_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "role catalog" ON public.portal_roles FOR SELECT TO authenticated USING (true);
CREATE TABLE public.portal_role_members (role_id uuid NOT NULL REFERENCES public.portal_roles(id) ON DELETE CASCADE, user_id uuid NOT NULL, PRIMARY KEY(role_id,user_id));
GRANT SELECT ON public.portal_role_members TO authenticated;
GRANT ALL ON public.portal_role_members TO service_role;
ALTER TABLE public.portal_role_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own role assignments or admin" ON public.portal_role_members FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_admin());
CREATE FUNCTION public.portal_permissions() RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(array_agg(DISTINCT p), '{}'::text[]) FROM public.portal_role_members m JOIN public.portal_roles r ON r.id=m.role_id CROSS JOIN unnest(r.permissions) p WHERE m.user_id=auth.uid() $$;
CREATE FUNCTION public.has_portal_permission(_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.is_admin() OR _permission=ANY(public.portal_permissions())) $$;
REVOKE ALL ON FUNCTION public.portal_permissions(), public.has_portal_permission(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.portal_permissions(), public.has_portal_permission(text) TO authenticated;
CREATE FUNCTION public.save_portal_role(_id uuid, _name text, _description text, _permissions text[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF; IF lower(trim(_name)) IN ('admin','administrator','resident') THEN RAISE EXCEPTION 'This role name is reserved'; END IF; IF _id IS NULL THEN INSERT INTO public.portal_roles(name,description,permissions) VALUES(trim(_name),_description,_permissions) RETURNING id INTO rid; ELSE UPDATE public.portal_roles SET name=trim(_name),description=_description,permissions=_permissions WHERE id=_id RETURNING id INTO rid; IF rid IS NULL THEN RAISE EXCEPTION 'Role not found'; END IF; END IF; PERFORM public.log_audit('save_role','role',rid::text,jsonb_build_object('name',_name,'permissions',_permissions)); RETURN rid; END $$;
CREATE FUNCTION public.assign_portal_roles(_resident_id uuid, _roles uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF; SELECT user_id INTO uid FROM public.residents WHERE id=_resident_id; IF uid IS NULL THEN RAISE EXCEPTION 'Resident has no account yet'; END IF; DELETE FROM public.portal_role_members WHERE user_id=uid; INSERT INTO public.portal_role_members(role_id,user_id) SELECT DISTINCT unnest(coalesce(_roles,'{}'::uuid[])),uid; PERFORM public.log_audit('assign_roles','resident',_resident_id::text,jsonb_build_object('roles',_roles)); END $$;
CREATE FUNCTION public.delete_portal_role(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF; DELETE FROM public.portal_roles WHERE id=_id; PERFORM public.log_audit('delete_role','role',_id::text,'{}'); END $$;
REVOKE ALL ON FUNCTION public.save_portal_role(uuid,text,text,text[]), public.assign_portal_roles(uuid,uuid[]), public.delete_portal_role(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_portal_role(uuid,text,text,text[]), public.assign_portal_roles(uuid,uuid[]), public.delete_portal_role(uuid) TO authenticated;
CREATE POLICY "delegated group management" ON public.household_groups FOR ALL TO authenticated USING (public.has_portal_permission('household.manage')) WITH CHECK (public.has_portal_permission('household.manage'));
CREATE POLICY "delegated group members" ON public.group_members FOR ALL TO authenticated USING (public.has_portal_permission('household.manage')) WITH CHECK (public.has_portal_permission('household.manage'));
CREATE POLICY "delegated space management" ON public.spaces FOR ALL TO authenticated USING (public.has_portal_permission('household.manage')) WITH CHECK (public.has_portal_permission('household.manage'));
CREATE POLICY "delegated washroom management" ON public.washroom_access FOR ALL TO authenticated USING (public.has_portal_permission('household.manage')) WITH CHECK (public.has_portal_permission('household.manage'));
CREATE POLICY "delegated issue management" ON public.issues FOR UPDATE TO authenticated USING (public.has_portal_permission('issues.manage')) WITH CHECK (public.has_portal_permission('issues.manage'));
CREATE POLICY "delegated audit read" ON public.audit_log FOR SELECT TO authenticated USING (public.has_portal_permission('audit.read'));